const fs = require("fs");
const path = require("path");
const { execFileSync, execSync } = require("child_process");

const root = process.cwd();
function P(...parts) { return path.join(root, ...parts); }
function fail(message) { console.error("\nERROR: " + message); process.exit(1); }

let branch = "";
try {
  branch = execFileSync("git", ["branch", "--show-current"], { cwd: root, encoding: "utf8" }).trim();
} catch {
  fail("تعذر قراءة فرع Git.");
}

if (branch !== "v2-dev") {
  fail("شغّل الملف داخل فرع v2-dev فقط. الفرع الحالي: " + branch);
}

const files = {
  backend: P("api","src","functions","manage-students.js"),
  login: P("api","src","functions","platform-login.js"),
  frontend: P("src","TeacherPlatform.tsx"),
  css: P("src","platform.css")
};

for (const file of Object.values(files)) {
  if (!fs.existsSync(file)) fail("الملف غير موجود: " + file);
}

const suffix = ".bak-phase2h-student-admin";
for (const file of Object.values(files)) {
  const backup = file + suffix;
  if (!fs.existsSync(backup)) fs.copyFileSync(file, backup);
}

const backend = "const { app } = require(\"@azure/functions\");\nconst { BlobServiceClient } = require(\"@azure/storage-blob\");\nconst crypto = require(\"crypto\");\nconst { requireBuilderAuth } = require(\"../lib/builder-auth\");\nconst {\n  studentCodeHash,\n  hashPassword,\n  generateTemporaryPassword\n} = require(\"../lib/student-auth\");\n\nconst BANK_CONTAINER = \"bank\";\nconst USER_PREFIX = \"platform/users/\";\nconst AUTH_PREFIX = \"platform/auth/\";\nconst CLASS_PREFIX = \"platform/classes/\";\nconst ASSIGNMENT_PREFIX = \"platform/assignments/\";\nconst SUBMISSION_PREFIX = \"platform/submissions/\";\n\nasync function streamToBuffer(stream) {\n  const chunks = [];\n  for await (const chunk of stream) chunks.push(Buffer.from(chunk));\n  return Buffer.concat(chunks);\n}\n\nfunction getContainer() {\n  const connectionString = process.env.AZURE_STORAGE_CONNECTION_STRING;\n  if (!connectionString) throw new Error(\"AZURE_STORAGE_CONNECTION_STRING is not configured.\");\n  return BlobServiceClient.fromConnectionString(connectionString).getContainerClient(BANK_CONTAINER);\n}\n\nasync function downloadJsonOrNull(container, blobName) {\n  try {\n    const response = await container.getBlobClient(blobName).download();\n    if (!response.readableStreamBody) return null;\n    return JSON.parse((await streamToBuffer(response.readableStreamBody)).toString(\"utf8\"));\n  } catch (error) {\n    if (error?.statusCode === 404 || error?.code === \"BlobNotFound\") return null;\n    throw error;\n  }\n}\n\nasync function uploadJson(container, blobName, document) {\n  const body = JSON.stringify(document, null, 2);\n  await container.getBlockBlobClient(blobName).upload(body, Buffer.byteLength(body), {\n    overwrite: true,\n    blobHTTPHeaders: { blobContentType: \"application/json; charset=utf-8\" }\n  });\n}\n\nasync function listJson(container, prefix) {\n  const result = [];\n  for await (const blob of container.listBlobsFlat({ prefix })) {\n    if (!blob.name.endsWith(\".json\")) continue;\n    const value = await downloadJsonOrNull(container, blob.name);\n    if (value) result.push(value);\n  }\n  return result;\n}\n\nfunction normalizeIdentityNumber(value) {\n  const digits = String(value ?? \"\").replace(/\\D/g, \"\");\n  if (!digits) return \"\";\n  return digits.length <= 9 ? digits.padStart(9, \"0\") : digits;\n}\n\nfunction isValidIdentityNumber(value) {\n  return /^\\d{9}$/.test(String(value || \"\"));\n}\n\nfunction splitLegacyName(value) {\n  const parts = String(value || \"\").trim().split(/\\s+/).filter(Boolean);\n  return { firstName: parts.shift() || \"\", familyName: parts.join(\" \") };\n}\n\nfunction getStudentNames(document) {\n  const legacy = splitLegacyName(document?.displayName);\n  return {\n    firstName: String(document?.firstName || legacy.firstName || \"\").trim(),\n    familyName: String(document?.familyName || legacy.familyName || \"\").trim()\n  };\n}\n\nfunction publicStudent(document) {\n  const names = getStudentNames(document);\n  const identityNumber = normalizeIdentityNumber(\n    document.identityNumber || (/^\\d{9}$/.test(String(document.code || \"\")) ? document.code : \"\")\n  );\n  return {\n    userId: String(document.userId || \"\"),\n    code: String(document.code || identityNumber || \"\"),\n    identityNumber,\n    firstName: names.firstName,\n    familyName: names.familyName,\n    displayName: String(document.displayName || [names.firstName, names.familyName].filter(Boolean).join(\" \")),\n    classId: String(document.classId || \"\"),\n    active: document.active !== false,\n    archived: document.archived === true,\n    createdAt: String(document.createdAt || \"\"),\n    updatedAt: String(document.updatedAt || \"\"),\n    lastLoginAt: String(document.lastLoginAt || \"\")\n  };\n}\n\nasync function getClassroom(container, classId) {\n  if (!classId) return null;\n  return downloadJsonOrNull(container, CLASS_PREFIX + classId + \".json\");\n}\n\nasync function saveClassroom(container, classroom) {\n  classroom.updatedAt = new Date().toISOString();\n  await uploadJson(container, CLASS_PREFIX + classroom.classId + \".json\", classroom);\n}\n\nfunction ensureStudentIds(classroom) {\n  classroom.studentIds = Array.isArray(classroom.studentIds) ? classroom.studentIds : [];\n  return classroom.studentIds;\n}\n\nasync function listStudents(container, classId, includeArchived = false) {\n  const result = [];\n  for await (const blob of container.listBlobsFlat({ prefix: USER_PREFIX })) {\n    if (!blob.name.endsWith(\".json\")) continue;\n    const student = await downloadJsonOrNull(container, blob.name);\n    if (!student || student.role !== \"student\") continue;\n    if (classId && String(student.classId || \"\") !== classId) continue;\n    if (!includeArchived && student.archived === true) continue;\n    result.push(publicStudent(student));\n  }\n  result.sort((a, b) => {\n    const family = String(a.familyName).localeCompare(String(b.familyName), \"ar\");\n    return family || String(a.firstName).localeCompare(String(b.firstName), \"ar\");\n  });\n  return result;\n}\n\nasync function findStudentByIdentity(container, identityNumber) {\n  if (!isValidIdentityNumber(identityNumber)) return null;\n  const auth = await downloadJsonOrNull(\n    container,\n    AUTH_PREFIX + studentCodeHash(identityNumber) + \".json\"\n  );\n  if (!auth?.userId) return null;\n  const student = await downloadJsonOrNull(container, USER_PREFIX + auth.userId + \".json\");\n  return student?.role === \"student\" ? student : null;\n}\n\nfunction namesFromInput(input) {\n  const directFirst = String(input?.firstName ?? input?.givenName ?? \"\").trim();\n  const directFamily = String(input?.familyName ?? input?.lastName ?? input?.surname ?? \"\").trim();\n  if (directFirst || directFamily) return { firstName: directFirst, familyName: directFamily };\n  return splitLegacyName(input?.displayName ?? input?.name ?? input?.studentName ?? \"\");\n}\n\nfunction identityFromInput(input) {\n  return normalizeIdentityNumber(\n    input?.identityNumber ??\n    input?.idNumber ??\n    input?.studentId ??\n    input?.identity ??\n    input?.id ??\n    input?.code ??\n    input?.studentCode ??\n    \"\"\n  );\n}\n\nfunction normalizeBulkStudents(value) {\n  const raw = Array.isArray(value) ? value : Array.isArray(value?.students) ? value.students : [];\n  return raw.map((item, index) => {\n    if (typeof item === \"string\") {\n      const names = splitLegacyName(item);\n      return { index, ...names, identityNumber: \"\" };\n    }\n    const names = namesFromInput(item);\n    return {\n      index,\n      firstName: names.firstName,\n      familyName: names.familyName,\n      identityNumber: identityFromInput(item)\n    };\n  }).filter(item => item.firstName || item.familyName || item.identityNumber);\n}\n\nasync function setAuthActive(container, student, active) {\n  const code = String(student.code || student.identityNumber || \"\");\n  if (!code) return;\n  const name = AUTH_PREFIX + studentCodeHash(code) + \".json\";\n  const auth = await downloadJsonOrNull(container, name);\n  if (!auth) return;\n  auth.active = active;\n  auth.updatedAt = new Date().toISOString();\n  await uploadJson(container, name, auth);\n}\n\nasync function createStudentRecord(container, classroom, input, options = {}) {\n  const { firstName, familyName } = namesFromInput(input);\n  const identityNumber = identityFromInput(input);\n  const code = identityNumber;\n\n  if (!firstName || !familyName) throw new Error(\"يجب إدخال الاسم الشخصي واسم العائلة.\");\n  if (!isValidIdentityNumber(identityNumber)) throw new Error(\"رقم الهوية يجب أن يتكوّن من 9 أرقام.\");\n\n  const existing = await findStudentByIdentity(container, identityNumber);\n  if (existing) {\n    const existingClass = await getClassroom(container, String(existing.classId || \"\"));\n    throw new Error(\n      \"رقم الهوية مستخدم مسبقًا للطالب \" +\n      String(existing.displayName || identityNumber) +\n      (existingClass?.name ? \" في الصف \" + existingClass.name : \"\")\n    );\n  }\n\n  const password = options.forceGeneratedPassword\n    ? generateTemporaryPassword()\n    : String(input?.password || \"\") || generateTemporaryPassword();\n\n  if (password.length < 6) throw new Error(\"كلمة المرور يجب أن تحتوي على 6 محارف على الأقل.\");\n\n  const { salt, passwordHash } = hashPassword(password);\n  const userId = crypto.randomUUID();\n  const now = new Date().toISOString();\n  const displayName = firstName + \" \" + familyName;\n\n  const student = {\n    schemaVersion: 3,\n    role: \"student\",\n    userId,\n    code,\n    identityNumber,\n    firstName,\n    familyName,\n    displayName,\n    classId: classroom.classId,\n    active: true,\n    archived: false,\n    createdAt: now,\n    updatedAt: now,\n    lastLoginAt: \"\"\n  };\n\n  const authDocument = {\n    schemaVersion: 3,\n    userId,\n    codeHash: studentCodeHash(code),\n    salt,\n    passwordHash,\n    active: true,\n    createdAt: now,\n    updatedAt: now\n  };\n\n  await uploadJson(container, USER_PREFIX + userId + \".json\", student);\n  await uploadJson(container, AUTH_PREFIX + studentCodeHash(code) + \".json\", authDocument);\n  const ids = ensureStudentIds(classroom);\n  if (!ids.includes(userId)) ids.push(userId);\n\n  return { student: publicStudent(student), temporaryPassword: password };\n}\n\nasync function resetStudentPassword(container, student, requestedPassword = \"\") {\n  const temporaryPassword = String(requestedPassword || \"\") || generateTemporaryPassword();\n  if (temporaryPassword.length < 6) throw new Error(\"كلمة المرور يجب أن تحتوي على 6 محارف على الأقل.\");\n\n  const code = String(student.code || student.identityNumber || \"\");\n  const authBlobName = AUTH_PREFIX + studentCodeHash(code) + \".json\";\n  const authDocument = await downloadJsonOrNull(container, authBlobName);\n  if (!authDocument) throw new Error(\"ملف دخول الطالب غير موجود.\");\n\n  const { salt, passwordHash } = hashPassword(temporaryPassword);\n  authDocument.salt = salt;\n  authDocument.passwordHash = passwordHash;\n  authDocument.updatedAt = new Date().toISOString();\n  await uploadJson(container, authBlobName, authDocument);\n  return temporaryPassword;\n}\n\nasync function changeStudentActive(container, student, active) {\n  if (student.archived === true && active) throw new Error(\"استعد الطالب من الأرشيف أولًا.\");\n  student.active = !!active;\n  student.updatedAt = new Date().toISOString();\n  await uploadJson(container, USER_PREFIX + student.userId + \".json\", student);\n  await setAuthActive(container, student, !!active);\n}\n\nasync function archiveStudent(container, student) {\n  if (student.archived === true) return;\n  student.archived = true;\n  student.active = false;\n  student.archivedAt = new Date().toISOString();\n  student.updatedAt = student.archivedAt;\n  await uploadJson(container, USER_PREFIX + student.userId + \".json\", student);\n  await setAuthActive(container, student, false);\n\n  const classroom = await getClassroom(container, String(student.classId || \"\"));\n  if (classroom) {\n    classroom.studentIds = ensureStudentIds(classroom).filter(id => id !== student.userId);\n    await saveClassroom(container, classroom);\n  }\n}\n\nasync function unarchiveStudent(container, student) {\n  if (student.archived !== true) return;\n  const classroom = await getClassroom(container, String(student.classId || \"\"));\n  if (!classroom || classroom.active === false) throw new Error(\"فعّل الصف قبل استعادة الطالب.\");\n\n  student.archived = false;\n  student.active = true;\n  student.archivedAt = \"\";\n  student.updatedAt = new Date().toISOString();\n  await uploadJson(container, USER_PREFIX + student.userId + \".json\", student);\n  await setAuthActive(container, student, true);\n\n  const ids = ensureStudentIds(classroom);\n  if (!ids.includes(student.userId)) ids.push(student.userId);\n  await saveClassroom(container, classroom);\n}\n\nasync function moveStudent(container, student, targetClassId) {\n  const target = await getClassroom(container, targetClassId);\n  if (!target || target.active === false) throw new Error(\"الصف الهدف غير موجود أو مؤرشف.\");\n\n  const oldClassId = String(student.classId || \"\");\n  if (oldClassId === targetClassId) return;\n\n  const oldClass = await getClassroom(container, oldClassId);\n  if (oldClass) {\n    oldClass.studentIds = ensureStudentIds(oldClass).filter(id => id !== student.userId);\n    await saveClassroom(container, oldClass);\n  }\n\n  student.classId = targetClassId;\n  student.updatedAt = new Date().toISOString();\n  await uploadJson(container, USER_PREFIX + student.userId + \".json\", student);\n\n  if (student.archived !== true) {\n    const ids = ensureStudentIds(target);\n    if (!ids.includes(student.userId)) ids.push(student.userId);\n    await saveClassroom(container, target);\n  }\n}\n\nasync function deleteStudent(container, student) {\n  const classroom = await getClassroom(container, String(student.classId || \"\"));\n  if (classroom) {\n    classroom.studentIds = ensureStudentIds(classroom).filter(id => id !== student.userId);\n    await saveClassroom(container, classroom);\n  }\n\n  const code = String(student.code || student.identityNumber || \"\");\n  if (code) {\n    await container.getBlobClient(AUTH_PREFIX + studentCodeHash(code) + \".json\").deleteIfExists();\n  }\n  await container.getBlobClient(USER_PREFIX + student.userId + \".json\").deleteIfExists();\n}\n\nasync function buildImportPreview(container, items) {\n  const classCache = new Map();\n  const rows = [];\n\n  for (const item of items) {\n    let status = \"valid\";\n    let error = \"\";\n    let existingStudent = null;\n\n    if (!item.firstName || !item.familyName) {\n      status = \"invalid\";\n      error = \"الاسم واسم العائلة مطلوبان.\";\n    } else if (!isValidIdentityNumber(item.identityNumber)) {\n      status = \"invalid\";\n      error = \"رقم الهوية يجب أن يتكوّن من 9 أرقام.\";\n    } else {\n      const existing = await findStudentByIdentity(container, item.identityNumber);\n      if (existing) {\n        status = \"duplicate\";\n        let classroom = null;\n        const classId = String(existing.classId || \"\");\n        if (classId) {\n          if (!classCache.has(classId)) classCache.set(classId, await getClassroom(container, classId));\n          classroom = classCache.get(classId);\n        }\n        existingStudent = {\n          userId: String(existing.userId || \"\"),\n          displayName: String(existing.displayName || \"\"),\n          classId,\n          className: String(classroom?.name || \"\"),\n          active: existing.active !== false,\n          archived: existing.archived === true\n        };\n        error = \"رقم الهوية موجود مسبقًا\" +\n          (existing.displayName ? \" للطالب \" + existing.displayName : \"\") +\n          (classroom?.name ? \" في الصف \" + classroom.name : \"\") + \".\";\n      }\n    }\n\n    rows.push({\n      index: item.index,\n      firstName: item.firstName,\n      familyName: item.familyName,\n      identityNumber: item.identityNumber,\n      status,\n      error,\n      existingStudent\n    });\n  }\n\n  return rows;\n}\n\nasync function buildStudentProfile(container, userId) {\n  const student = await downloadJsonOrNull(container, USER_PREFIX + userId + \".json\");\n  if (!student || student.role !== \"student\") return null;\n\n  const classroom = await getClassroom(container, String(student.classId || \"\"));\n  const assignments = (await listJson(container, ASSIGNMENT_PREFIX))\n    .filter(a => String(a.classId || \"\") === String(student.classId || \"\"))\n    .sort((a, b) => String(b.createdAt || \"\").localeCompare(String(a.createdAt || \"\")));\n\n  const history = [];\n  let completed = 0;\n  let percentageSum = 0;\n\n  for (const assignment of assignments) {\n    const submission = await downloadJsonOrNull(\n      container,\n      SUBMISSION_PREFIX + assignment.assignmentId + \"/\" + student.userId + \".json\"\n    );\n    const attempts = Array.isArray(submission?.attempts) ? submission.attempts : [];\n    const latest = attempts.length ? attempts[attempts.length - 1] : null;\n\n    if (latest) {\n      completed += 1;\n      percentageSum += Number(latest.percentage || 0);\n    }\n\n    history.push({\n      assignmentId: String(assignment.assignmentId || \"\"),\n      title: String(assignment.title || \"\"),\n      status: String(assignment.status || \"\"),\n      dueAt: String(assignment.dueAt || \"\"),\n      totalMarks: Number(assignment.totalMarks || 0),\n      attemptsUsed: attempts.length,\n      latestScore: latest ? Number(latest.score || 0) : null,\n      latestPercentage: latest ? Number(latest.percentage || 0) : null,\n      submittedAt: latest ? String(latest.submittedAt || \"\") : \"\",\n      finalized: latest ? latest.finalized === true : false\n    });\n  }\n\n  return {\n    student: publicStudent(student),\n    classroom: classroom ? {\n      classId: String(classroom.classId || \"\"),\n      name: String(classroom.name || \"\"),\n      grade: String(classroom.grade || \"\"),\n      schoolYear: String(classroom.schoolYear || \"\")\n    } : null,\n    stats: {\n      assigned: assignments.length,\n      completed,\n      pending: Math.max(0, assignments.length - completed),\n      average: completed ? Number((percentageSum / completed).toFixed(1)) : null,\n      lastLoginAt: String(student.lastLoginAt || \"\")\n    },\n    assignments: history\n  };\n}\n\napp.http(\"manageStudents\", {\n  methods: [\"GET\", \"POST\"],\n  authLevel: \"anonymous\",\n  route: \"students\",\n  handler: async request => {\n    try {\n      const auth = requireBuilderAuth(request);\n      if (!auth.ok) return auth.response;\n      const container = getContainer();\n\n      if (request.method === \"GET\") {\n        const url = new URL(request.url);\n        const profileUserId = String(url.searchParams.get(\"profileUserId\") || \"\").trim();\n\n        if (profileUserId) {\n          const profile = await buildStudentProfile(container, profileUserId);\n          if (!profile) return { status: 404, jsonBody: { ok: false, error: \"الطالب غير موجود.\" } };\n          return { status: 200, jsonBody: { ok: true, profile } };\n        }\n\n        const classId = String(url.searchParams.get(\"classId\") || \"\").trim();\n        const includeArchived = url.searchParams.get(\"includeArchived\") === \"1\";\n        return {\n          status: 200,\n          jsonBody: { ok: true, students: await listStudents(container, classId, includeArchived) }\n        };\n      }\n\n      let body = {};\n      try { body = await request.json(); } catch { body = {}; }\n      const action = String(body?.action || \"create\").trim().toLowerCase();\n\n      if (action === \"create\") {\n        const classId = String(body?.classId || \"\").trim();\n        const classroom = await getClassroom(container, classId);\n        if (!classroom || classroom.active === false) {\n          return { status: 400, jsonBody: { ok: false, error: \"الصف غير موجود أو مؤرشف.\" } };\n        }\n\n        const result = await createStudentRecord(container, classroom, body, { forceGeneratedPassword: false });\n        await saveClassroom(container, classroom);\n        return { status: 200, jsonBody: { ok: true, ...result } };\n      }\n\n      if (action === \"previewimport\") {\n        const students = normalizeBulkStudents(body?.students ?? body?.data);\n        if (!students.length) {\n          return { status: 400, jsonBody: { ok: false, error: \"ملف JSON لا يحتوي بيانات طلاب صالحة.\" } };\n        }\n        if (students.length > 250) {\n          return { status: 400, jsonBody: { ok: false, error: \"يمكن فحص 250 طالبًا كحد أقصى في العملية الواحدة.\" } };\n        }\n        const preview = await buildImportPreview(container, students);\n        return {\n          status: 200,\n          jsonBody: {\n            ok: true,\n            preview,\n            valid: preview.filter(x => x.status === \"valid\").length,\n            duplicates: preview.filter(x => x.status === \"duplicate\").length,\n            invalid: preview.filter(x => x.status === \"invalid\").length\n          }\n        };\n      }\n\n      if (action === \"bulkimport\") {\n        const classId = String(body?.classId || \"\").trim();\n        const classroom = await getClassroom(container, classId);\n        if (!classroom || classroom.active === false) {\n          return { status: 400, jsonBody: { ok: false, error: \"الصف غير موجود أو مؤرشف.\" } };\n        }\n\n        const students = normalizeBulkStudents(body?.students ?? body?.data);\n        if (!students.length) {\n          return { status: 400, jsonBody: { ok: false, error: \"ملف JSON لا يحتوي بيانات طلاب صالحة.\" } };\n        }\n        if (students.length > 250) {\n          return { status: 400, jsonBody: { ok: false, error: \"يمكن استيراد 250 طالبًا كحد أقصى في العملية الواحدة.\" } };\n        }\n\n        const credentials = [];\n        const errors = [];\n\n        for (const item of students) {\n          try {\n            const result = await createStudentRecord(container, classroom, item, { forceGeneratedPassword: true });\n            credentials.push({\n              userId: result.student.userId,\n              firstName: result.student.firstName,\n              familyName: result.student.familyName,\n              displayName: result.student.displayName,\n              identityNumber: result.student.identityNumber,\n              code: result.student.code,\n              password: result.temporaryPassword\n            });\n          } catch (error) {\n            errors.push({\n              index: item.index,\n              firstName: item.firstName,\n              familyName: item.familyName,\n              identityNumber: item.identityNumber,\n              displayName: [item.firstName, item.familyName].filter(Boolean).join(\" \"),\n              code: item.identityNumber || \"\",\n              error: error instanceof Error ? error.message : \"تعذر إنشاء الطالب.\"\n            });\n          }\n        }\n\n        await saveClassroom(container, classroom);\n        return {\n          status: 200,\n          jsonBody: {\n            ok: true,\n            imported: credentials.length,\n            failed: errors.length,\n            credentials,\n            errors\n          }\n        };\n      }\n\n      if (action === \"update\") {\n        const userId = String(body?.userId || \"\").trim();\n        const studentBlobName = USER_PREFIX + userId + \".json\";\n        const student = await downloadJsonOrNull(container, studentBlobName);\n\n        if (!student || student.role !== \"student\") {\n          return { status: 404, jsonBody: { ok: false, error: \"الطالب غير موجود.\" } };\n        }\n\n        const currentNames = getStudentNames(student);\n        const firstName = String(body?.firstName ?? currentNames.firstName ?? \"\").trim();\n        const familyName = String(body?.familyName ?? currentNames.familyName ?? \"\").trim();\n        const identityNumber = normalizeIdentityNumber(\n          body?.identityNumber ??\n          body?.code ??\n          student.identityNumber ??\n          (/^\\d{9}$/.test(String(student.code || \"\")) ? student.code : \"\")\n        );\n        const newCode = identityNumber;\n        const newClassId = String(body?.classId ?? student.classId ?? \"\").trim();\n        const newPassword = String(body?.password || \"\");\n\n        if (!firstName || !familyName) {\n          return { status: 400, jsonBody: { ok: false, error: \"يجب إدخال الاسم الشخصي واسم العائلة.\" } };\n        }\n        if (!isValidIdentityNumber(identityNumber)) {\n          return { status: 400, jsonBody: { ok: false, error: \"رقم الهوية يجب أن يتكوّن من 9 أرقام.\" } };\n        }\n        if (!newClassId) return { status: 400, jsonBody: { ok: false, error: \"اختر الصف.\" } };\n        if (newPassword && newPassword.length < 6) {\n          return { status: 400, jsonBody: { ok: false, error: \"كلمة المرور الجديدة يجب أن تحتوي على 6 محارف على الأقل.\" } };\n        }\n\n        const newClassroom = await getClassroom(container, newClassId);\n        if (!newClassroom || newClassroom.active === false) {\n          return { status: 400, jsonBody: { ok: false, error: \"الصف الجديد غير موجود أو مؤرشف.\" } };\n        }\n\n        const oldCode = String(student.code || student.identityNumber || \"\");\n        if (newCode !== oldCode) {\n          const duplicate = await findStudentByIdentity(container, newCode);\n          if (duplicate && String(duplicate.userId) !== userId) {\n            return { status: 409, jsonBody: { ok: false, error: \"رقم الهوية مستخدم مسبقًا.\" } };\n          }\n        }\n\n        const oldClassId = String(student.classId || \"\");\n        const oldAuthName = AUTH_PREFIX + studentCodeHash(oldCode) + \".json\";\n        const oldAuth = await downloadJsonOrNull(container, oldAuthName);\n        if (!oldAuth) {\n          return { status: 404, jsonBody: { ok: false, error: \"ملف دخول الطالب غير موجود.\" } };\n        }\n\n        student.schemaVersion = 3;\n        student.firstName = firstName;\n        student.familyName = familyName;\n        student.displayName = firstName + \" \" + familyName;\n        student.identityNumber = identityNumber;\n        student.code = newCode;\n        student.classId = newClassId;\n        student.updatedAt = new Date().toISOString();\n\n        if (newPassword) {\n          const { salt, passwordHash } = hashPassword(newPassword);\n          oldAuth.salt = salt;\n          oldAuth.passwordHash = passwordHash;\n        }\n\n        oldAuth.schemaVersion = 3;\n        oldAuth.codeHash = studentCodeHash(newCode);\n        oldAuth.active = student.active !== false && student.archived !== true;\n        oldAuth.updatedAt = new Date().toISOString();\n\n        await uploadJson(container, studentBlobName, student);\n        const newAuthName = AUTH_PREFIX + studentCodeHash(newCode) + \".json\";\n        await uploadJson(container, newAuthName, oldAuth);\n        if (newAuthName !== oldAuthName) await container.getBlobClient(oldAuthName).deleteIfExists();\n\n        if (oldClassId !== newClassId) {\n          const oldClassroom = await getClassroom(container, oldClassId);\n          if (oldClassroom) {\n            oldClassroom.studentIds = ensureStudentIds(oldClassroom).filter(id => id !== userId);\n            await saveClassroom(container, oldClassroom);\n          }\n          if (student.archived !== true) {\n            const ids = ensureStudentIds(newClassroom);\n            if (!ids.includes(userId)) ids.push(userId);\n            await saveClassroom(container, newClassroom);\n          }\n        }\n\n        return {\n          status: 200,\n          jsonBody: { ok: true, student: publicStudent(student), passwordChanged: !!newPassword }\n        };\n      }\n\n      if ([\"resetpassword\", \"toggleactive\", \"archive\", \"unarchive\", \"delete\"].includes(action)) {\n        const userId = String(body?.userId || \"\").trim();\n        const student = await downloadJsonOrNull(container, USER_PREFIX + userId + \".json\");\n        if (!student || student.role !== \"student\") {\n          return { status: 404, jsonBody: { ok: false, error: \"الطالب غير موجود.\" } };\n        }\n\n        if (action === \"resetpassword\") {\n          const temporaryPassword = await resetStudentPassword(container, student, body?.password);\n          return { status: 200, jsonBody: { ok: true, temporaryPassword } };\n        }\n        if (action === \"toggleactive\") {\n          const active = !(student.active !== false);\n          await changeStudentActive(container, student, active);\n          return { status: 200, jsonBody: { ok: true, active } };\n        }\n        if (action === \"archive\") {\n          await archiveStudent(container, student);\n          return { status: 200, jsonBody: { ok: true, archived: true } };\n        }\n        if (action === \"unarchive\") {\n          await unarchiveStudent(container, student);\n          return { status: 200, jsonBody: { ok: true, archived: false, active: true } };\n        }\n\n        await deleteStudent(container, student);\n        return { status: 200, jsonBody: { ok: true, deleted: true } };\n      }\n\n      if (action === \"bulkaction\") {\n        const operation = String(body?.operation || \"\").trim().toLowerCase();\n        const userIds = Array.from(new Set(\n          (Array.isArray(body?.userIds) ? body.userIds : [])\n            .map(x => String(x || \"\").trim())\n            .filter(Boolean)\n        )).slice(0, 250);\n\n        if (!userIds.length) {\n          return { status: 400, jsonBody: { ok: false, error: \"اختر طالبًا واحدًا على الأقل.\" } };\n        }\n\n        const supported = [\"activate\", \"deactivate\", \"archive\", \"unarchive\", \"move\", \"resetpasswords\", \"delete\"];\n        if (!supported.includes(operation)) {\n          return { status: 400, jsonBody: { ok: false, error: \"العملية الجماعية غير مدعومة.\" } };\n        }\n\n        const targetClassId = String(body?.targetClassId || \"\").trim();\n        if (operation === \"move\" && !targetClassId) {\n          return { status: 400, jsonBody: { ok: false, error: \"اختر الصف الهدف.\" } };\n        }\n\n        const results = [];\n        const errors = [];\n        const credentials = [];\n\n        for (const userId of userIds) {\n          try {\n            const student = await downloadJsonOrNull(container, USER_PREFIX + userId + \".json\");\n            if (!student || student.role !== \"student\") throw new Error(\"الطالب غير موجود.\");\n\n            if (operation === \"activate\") await changeStudentActive(container, student, true);\n            else if (operation === \"deactivate\") await changeStudentActive(container, student, false);\n            else if (operation === \"archive\") await archiveStudent(container, student);\n            else if (operation === \"unarchive\") await unarchiveStudent(container, student);\n            else if (operation === \"move\") await moveStudent(container, student, targetClassId);\n            else if (operation === \"resetpasswords\") {\n              const password = await resetStudentPassword(container, student);\n              const publicValue = publicStudent(student);\n              credentials.push({\n                userId,\n                firstName: publicValue.firstName,\n                familyName: publicValue.familyName,\n                displayName: publicValue.displayName,\n                identityNumber: publicValue.identityNumber,\n                code: publicValue.code,\n                password\n              });\n            } else if (operation === \"delete\") await deleteStudent(container, student);\n\n            results.push(userId);\n          } catch (error) {\n            errors.push({\n              userId,\n              error: error instanceof Error ? error.message : \"تعذر تنفيذ العملية.\"\n            });\n          }\n        }\n\n        return {\n          status: 200,\n          jsonBody: {\n            ok: true,\n            processed: results.length,\n            failed: errors.length,\n            results,\n            errors,\n            credentials\n          }\n        };\n      }\n\n      return {\n        status: 400,\n        jsonBody: { ok: false, error: \"Unsupported student action.\" }\n      };\n    } catch (error) {\n      return {\n        status: 500,\n        jsonBody: {\n          ok: false,\n          error: error instanceof Error ? error.message : \"Student action failed.\"\n        }\n      };\n    }\n  }\n});\n";
const login = "const { app } = require(\"@azure/functions\");\nconst { BlobServiceClient } = require(\"@azure/storage-blob\");\nconst {\n  TOKEN_TTL_SECONDS,\n  createBuilderToken,\n  validateBuilderCredentials\n} = require(\"../lib/builder-auth\");\nconst {\n  STUDENT_TOKEN_TTL_SECONDS,\n  normalizeStudentCode,\n  studentCodeHash,\n  verifyPassword,\n  createStudentToken\n} = require(\"../lib/student-auth\");\n\nconst BANK_CONTAINER = \"bank\";\n\nasync function streamToBuffer(stream) {\n  const chunks = [];\n  for await (const chunk of stream) chunks.push(Buffer.from(chunk));\n  return Buffer.concat(chunks);\n}\n\nfunction getContainer() {\n  const connectionString = process.env.AZURE_STORAGE_CONNECTION_STRING;\n  if (!connectionString) throw new Error(\"AZURE_STORAGE_CONNECTION_STRING is not configured.\");\n  return BlobServiceClient.fromConnectionString(connectionString).getContainerClient(BANK_CONTAINER);\n}\n\nasync function downloadJsonOrNull(container, blobName) {\n  try {\n    const response = await container.getBlobClient(blobName).download();\n    if (!response.readableStreamBody) return null;\n    return JSON.parse((await streamToBuffer(response.readableStreamBody)).toString(\"utf8\"));\n  } catch (error) {\n    if (error?.statusCode === 404 || error?.code === \"BlobNotFound\") return null;\n    throw error;\n  }\n}\n\nasync function uploadJson(container, blobName, document) {\n  const body = JSON.stringify(document, null, 2);\n  await container.getBlockBlobClient(blobName).upload(body, Buffer.byteLength(body), {\n    overwrite: true,\n    blobHTTPHeaders: { blobContentType: \"application/json; charset=utf-8\" }\n  });\n}\n\napp.http(\"platformLogin\", {\n  methods: [\"POST\"],\n  authLevel: \"anonymous\",\n  route: \"platform-login\",\n  handler: async request => {\n    try {\n      let body = {};\n      try { body = await request.json(); } catch { body = {}; }\n\n      const userCode = String(body?.userCode || \"\").trim();\n      const password = String(body?.password || \"\");\n      if (!userCode || !password) {\n        return {\n          status: 400,\n          jsonBody: { ok: false, error: \"كود المستخدم / رقم الهوية وكلمة المرور مطلوبان.\" }\n        };\n      }\n\n      let isTeacher = false;\n      try { isTeacher = validateBuilderCredentials(userCode, password); } catch { isTeacher = false; }\n\n      if (isTeacher) {\n        const token = createBuilderToken(userCode);\n        return {\n          status: 200,\n          jsonBody: {\n            ok: true,\n            role: \"teacher\",\n            token,\n            userCode,\n            displayName: \"المعلم\",\n            expiresInSeconds: TOKEN_TTL_SECONDS\n          }\n        };\n      }\n\n      const normalizedCode = normalizeStudentCode(userCode);\n      const container = getContainer();\n      const authDocument = await downloadJsonOrNull(\n        container,\n        \"platform/auth/\" + studentCodeHash(normalizedCode) + \".json\"\n      );\n\n      if (\n        !authDocument ||\n        authDocument.active === false ||\n        !verifyPassword(password, authDocument.salt, authDocument.passwordHash)\n      ) {\n        return { status: 401, jsonBody: { ok: false, error: \"بيانات الدخول غير صحيحة.\" } };\n      }\n\n      const studentBlobName = \"platform/users/\" + authDocument.userId + \".json\";\n      const student = await downloadJsonOrNull(container, studentBlobName);\n      if (!student || student.active === false || student.archived === true) {\n        return { status: 401, jsonBody: { ok: false, error: \"الحساب غير فعّال.\" } };\n      }\n\n      const now = new Date().toISOString();\n      student.lastLoginAt = now;\n      student.updatedAt = now;\n      await uploadJson(container, studentBlobName, student);\n\n      const token = createStudentToken(student);\n      return {\n        status: 200,\n        jsonBody: {\n          ok: true,\n          role: \"student\",\n          token,\n          userCode: student.code,\n          displayName: student.displayName,\n          expiresInSeconds: STUDENT_TOKEN_TTL_SECONDS\n        }\n      };\n    } catch (error) {\n      return {\n        status: 500,\n        jsonBody: {\n          ok: false,\n          error: error instanceof Error ? error.message : \"Platform login failed.\"\n        }\n      };\n    }\n  }\n});\n";
const frontend = "import {useEffect,useMemo,useState} from \"react\";\nimport AssignmentsPanel from \"./AssignmentsPanel\";\n\ntype TeacherPlatformProps={token:string;currentExam:unknown|null};\ntype Classroom={classId:string;name:string;grade:string;schoolYear:string;active:boolean;studentCount:number;createdAt:string};\ntype Student={userId:string;code:string;identityNumber:string;firstName:string;familyName:string;displayName:string;classId:string;active:boolean;archived:boolean;createdAt:string;updatedAt:string;lastLoginAt:string};\ntype Credential={userId?:string;firstName?:string;familyName?:string;displayName?:string;code:string;identityNumber?:string;password:string};\ntype BulkStudent={firstName:string;familyName:string;identityNumber:string};\ntype BulkError={index?:number;firstName?:string;familyName?:string;identityNumber?:string;displayName?:string;code?:string;error:string;userId?:string};\ntype ImportPreviewRow={index:number;firstName:string;familyName:string;identityNumber:string;status:\"valid\"|\"duplicate\"|\"invalid\";error:string;existingStudent?:{userId:string;displayName:string;classId:string;className:string;active:boolean;archived:boolean}|null};\ntype StudentProfile={\n student:Student;\n classroom:{classId:string;name:string;grade:string;schoolYear:string}|null;\n stats:{assigned:number;completed:number;pending:number;average:number|null;lastLoginAt:string};\n assignments:Array<{assignmentId:string;title:string;status:string;dueAt:string;totalMarks:number;attemptsUsed:number;latestScore:number|null;latestPercentage:number|null;submittedAt:string;finalized:boolean}>\n};\ntype ApiError={ok?:boolean;error?:string};\ntype SortKey=\"firstName\"|\"familyName\"|\"identityNumber\"|\"status\";\ntype StatusFilter=\"all\"|\"active\"|\"disabled\"|\"archived\";\n\nconst onlyDigits=(value:string)=>value.replace(/\\D/g,\"\").slice(0,9);\nconst validIdentity=(value:string)=>/^\\d{9}$/.test(value);\nconst fmtDate=(value:string)=>value?new Date(value).toLocaleString(\"ar\"):\"—\";\n\nfunction normalizeImportedIdentity(value:unknown){\n const digits=String(value??\"\").replace(/\\D/g,\"\");\n return digits&&digits.length<=9?digits.padStart(9,\"0\"):digits;\n}\nfunction splitName(value:unknown){\n const parts=String(value??\"\").trim().split(/\\s+/).filter(Boolean);\n return {firstName:parts.shift()||\"\",familyName:parts.join(\" \")};\n}\nfunction statusLabel(student:Student){\n if(student.archived)return \"مؤرشف\";\n return student.active?\"فعّال\":\"معطّل\";\n}\nfunction csvCell(value:unknown){\n const text=String(value??\"\");\n return `\"${text.replace(/\"/g,'\"\"')}\"`;\n}\n\nfunction TeacherPlatform({token,currentExam}:TeacherPlatformProps){\n const [classes,setClasses]=useState<Classroom[]>([]);\n const [students,setStudents]=useState<Student[]>([]);\n const [selectedClassId,setSelectedClassId]=useState(\"\");\n const [loading,setLoading]=useState(false);\n const [actionBusy,setActionBusy]=useState(false);\n const [error,setError]=useState(\"\");\n const [notice,setNotice]=useState(\"\");\n\n const [newClassName,setNewClassName]=useState(\"\");\n const [newClassGrade,setNewClassGrade]=useState(\"\");\n const [newSchoolYear,setNewSchoolYear]=useState(String(new Date().getFullYear())+\"-\"+String(new Date().getFullYear()+1));\n\n const [newFirstName,setNewFirstName]=useState(\"\");\n const [newFamilyName,setNewFamilyName]=useState(\"\");\n const [newIdentityNumber,setNewIdentityNumber]=useState(\"\");\n const [newStudentPassword,setNewStudentPassword]=useState(\"\");\n\n const [credentialBox,setCredentialBox]=useState<{name:string;identityNumber:string;password:string}|null>(null);\n const [bulkCredentials,setBulkCredentials]=useState<Credential[]>([]);\n const [bulkErrors,setBulkErrors]=useState<BulkError[]>([]);\n\n const [bulkStudents,setBulkStudents]=useState<BulkStudent[]>([]);\n const [bulkFileName,setBulkFileName]=useState(\"\");\n const [importPreview,setImportPreview]=useState<ImportPreviewRow[]>([]);\n const [previewBusy,setPreviewBusy]=useState(false);\n\n const [editingStudent,setEditingStudent]=useState<Student|null>(null);\n const [editFirstName,setEditFirstName]=useState(\"\");\n const [editFamilyName,setEditFamilyName]=useState(\"\");\n const [editIdentityNumber,setEditIdentityNumber]=useState(\"\");\n const [editClassId,setEditClassId]=useState(\"\");\n const [editPassword,setEditPassword]=useState(\"\");\n\n const [searchText,setSearchText]=useState(\"\");\n const [statusFilter,setStatusFilter]=useState<StatusFilter>(\"all\");\n const [sortKey,setSortKey]=useState<SortKey>(\"familyName\");\n const [sortAsc,setSortAsc]=useState(true);\n const [selectedIds,setSelectedIds]=useState<string[]>([]);\n const [bulkTargetClassId,setBulkTargetClassId]=useState(\"\");\n\n const [profile,setProfile]=useState<StudentProfile|null>(null);\n const [profileBusy,setProfileBusy]=useState(false);\n\n const selectedClass=useMemo(()=>classes.find(c=>c.classId===selectedClassId)||null,[classes,selectedClassId]);\n\n const stats=useMemo(()=>{\n  const current=students.filter(s=>!s.archived);\n  return {\n   total:students.length,\n   active:current.filter(s=>s.active).length,\n   disabled:current.filter(s=>!s.active).length,\n   archived:students.filter(s=>s.archived).length,\n   neverLogged:students.filter(s=>!s.archived&&!s.lastLoginAt).length\n  };\n },[students]);\n\n const visibleStudents=useMemo(()=>{\n  const q=searchText.trim().toLocaleLowerCase(\"ar\");\n  const filtered=students.filter(student=>{\n   if(statusFilter===\"active\"&&(student.archived||!student.active))return false;\n   if(statusFilter===\"disabled\"&&(student.archived||student.active))return false;\n   if(statusFilter===\"archived\"&&!student.archived)return false;\n   if(!q)return true;\n   const hay=[student.firstName,student.familyName,student.displayName,student.identityNumber,student.code].join(\" \").toLocaleLowerCase(\"ar\");\n   return hay.includes(q);\n  });\n\n  const factor=sortAsc?1:-1;\n  return [...filtered].sort((a,b)=>{\n   let av=\"\",bv=\"\";\n   if(sortKey===\"status\"){av=statusLabel(a);bv=statusLabel(b)}\n   else {av=String(a[sortKey]||\"\");bv=String(b[sortKey]||\"\")}\n   return av.localeCompare(bv,\"ar\",{numeric:true})*factor;\n  });\n },[students,searchText,statusFilter,sortKey,sortAsc]);\n\n async function teacherApi<T>(url:string,options:RequestInit={}):Promise<T>{\n  const headers=new Headers(options.headers||{});\n  headers.set(\"Content-Type\",\"application/json\");\n  headers.set(\"x-builder-token\",token);\n  headers.set(\"Authorization\",\"Bearer \"+token);\n  const response=await fetch(url,{...options,headers});\n  const result=await response.json() as T&ApiError;\n  if(!response.ok)throw new Error(result.error||\"حدث خطأ.\");\n  return result;\n }\n\n async function loadClasses(preserveSelection=true){\n  setLoading(true);setError(\"\");\n  try{\n   const result=await teacherApi<{ok:true;classes:Classroom[]}>(\"/api/classrooms\");\n   const loaded=result.classes||[];\n   setClasses(loaded);\n   if(!preserveSelection||!selectedClassId||!loaded.some(c=>c.classId===selectedClassId)){\n    const first=loaded.find(c=>c.active)||loaded[0];\n    setSelectedClassId(first?.classId||\"\");\n   }\n  }catch(e){setError(e instanceof Error?e.message:\"تعذر تحميل الصفوف.\")}\n  finally{setLoading(false)}\n }\n\n async function loadStudents(classId:string){\n  if(!classId){setStudents([]);return}\n  setLoading(true);setError(\"\");\n  try{\n   const result=await teacherApi<{ok:true;students:Student[]}>(\"/api/students?classId=\"+encodeURIComponent(classId)+\"&includeArchived=1\");\n   setStudents(result.students||[]);\n   setSelectedIds(prev=>prev.filter(id=>(result.students||[]).some(s=>s.userId===id)));\n  }catch(e){setError(e instanceof Error?e.message:\"تعذر تحميل الطلاب.\")}\n  finally{setLoading(false)}\n }\n\n useEffect(()=>{void loadClasses(false)},[]);\n useEffect(()=>{\n  setSelectedIds([]);setProfile(null);setEditingStudent(null);\n  if(selectedClassId)void loadStudents(selectedClassId);else setStudents([]);\n },[selectedClassId]);\n\n async function createClass(){\n  if(!newClassName.trim()||actionBusy)return;\n  setActionBusy(true);setError(\"\");setNotice(\"\");\n  try{\n   const result=await teacherApi<{ok:true;classroom:Classroom}>(\"/api/classrooms\",{method:\"POST\",body:JSON.stringify({action:\"create\",name:newClassName.trim(),grade:newClassGrade.trim(),schoolYear:newSchoolYear.trim()})});\n   setNewClassName(\"\");setNewClassGrade(\"\");\n   await loadClasses(false);\n   setSelectedClassId(result.classroom.classId);\n   setNotice(\"✓ تم إنشاء الصف.\");\n  }catch(e){setError(e instanceof Error?e.message:\"تعذر إنشاء الصف.\")}\n  finally{setActionBusy(false)}\n }\n\n async function toggleClassArchive(classroom:Classroom){\n  if(actionBusy)return;\n  setActionBusy(true);setError(\"\");setNotice(\"\");\n  try{\n   await teacherApi(\"/api/classrooms\",{method:\"POST\",body:JSON.stringify({action:classroom.active?\"archive\":\"unarchive\",classId:classroom.classId})});\n   await loadClasses();\n   setNotice(classroom.active?\"✓ تم أرشفة الصف.\":\"✓ تم تفعيل الصف.\");\n  }catch(e){setError(e instanceof Error?e.message:\"تعذر تعديل الصف.\")}\n  finally{setActionBusy(false)}\n }\n\n async function createStudent(){\n  if(!selectedClassId||!newFirstName.trim()||!newFamilyName.trim()||!validIdentity(newIdentityNumber)||actionBusy)return;\n  setActionBusy(true);setError(\"\");setNotice(\"\");setCredentialBox(null);\n  try{\n   const result=await teacherApi<{ok:true;student:Student;temporaryPassword:string}>(\"/api/students\",{method:\"POST\",body:JSON.stringify({\n    action:\"create\",classId:selectedClassId,firstName:newFirstName.trim(),familyName:newFamilyName.trim(),identityNumber:newIdentityNumber,password:newStudentPassword\n   })});\n   setCredentialBox({name:result.student.displayName,identityNumber:result.student.identityNumber,password:result.temporaryPassword});\n   setNewFirstName(\"\");setNewFamilyName(\"\");setNewIdentityNumber(\"\");setNewStudentPassword(\"\");\n   await Promise.all([loadStudents(selectedClassId),loadClasses()]);\n   setNotice(\"✓ تم إنشاء حساب الطالب. سيستخدم رقم الهوية لتسجيل الدخول.\");\n  }catch(e){setError(e instanceof Error?e.message:\"تعذر إنشاء الطالب.\")}\n  finally{setActionBusy(false)}\n }\n\n async function copyText(text:string,success:string){\n  try{\n   await navigator.clipboard.writeText(text);\n   setNotice(success);\n  }catch{\n   setError(\"تعذر النسخ تلقائيًا. يمكنك تحديد النص ونسخه يدويًا.\");\n  }\n }\n\n function credentialText(name:string,identityNumber:string,password:string){\n  return `الطالب: ${name}\\nرقم الهوية / الدخول: ${identityNumber}\\nكلمة المرور: ${password}`;\n }\n\n async function resetPassword(student:Student){\n  if(actionBusy||student.archived||!window.confirm(\"إنشاء كلمة مرور جديدة للطالب \"+student.displayName+\"؟\"))return;\n  setActionBusy(true);setError(\"\");setNotice(\"\");setCredentialBox(null);\n  try{\n   const result=await teacherApi<{ok:true;temporaryPassword:string}>(\"/api/students\",{method:\"POST\",body:JSON.stringify({action:\"resetPassword\",userId:student.userId})});\n   setCredentialBox({name:student.displayName,identityNumber:student.identityNumber||student.code,password:result.temporaryPassword});\n   setNotice(\"✓ تم تغيير كلمة المرور. يمكنك الآن نسخ بيانات الدخول.\");\n  }catch(e){setError(e instanceof Error?e.message:\"تعذر تغيير كلمة المرور.\")}\n  finally{setActionBusy(false)}\n }\n\n async function toggleStudent(student:Student){\n  if(actionBusy||student.archived)return;\n  setActionBusy(true);setError(\"\");setNotice(\"\");\n  try{\n   await teacherApi(\"/api/students\",{method:\"POST\",body:JSON.stringify({action:\"toggleActive\",userId:student.userId})});\n   await loadStudents(selectedClassId);\n   setNotice(student.active?\"✓ تم تعطيل حساب الطالب.\":\"✓ تم تفعيل حساب الطالب.\");\n  }catch(e){setError(e instanceof Error?e.message:\"تعذر تعديل الحساب.\")}\n  finally{setActionBusy(false)}\n }\n\n async function archiveStudent(student:Student){\n  const action=student.archived?\"unarchive\":\"archive\";\n  const message=student.archived\n   ?\"استعادة الطالب \"+student.displayName+\" إلى الصف وتفعيل حسابه؟\"\n   :\"أرشفة الطالب \"+student.displayName+\"؟\\n\\nسيُزال من عدد طلاب الصف الفعّالين ويُمنع من تسجيل الدخول، مع الاحتفاظ ببياناته ونتائجه.\";\n  if(actionBusy||!window.confirm(message))return;\n  setActionBusy(true);setError(\"\");setNotice(\"\");\n  try{\n   await teacherApi(\"/api/students\",{method:\"POST\",body:JSON.stringify({action,userId:student.userId})});\n   await Promise.all([loadStudents(selectedClassId),loadClasses()]);\n   setNotice(student.archived?\"✓ تمت استعادة الطالب.\":\"✓ تمت أرشفة الطالب مع الاحتفاظ ببياناته.\");\n  }catch(e){setError(e instanceof Error?e.message:\"تعذر تغيير حالة الأرشفة.\")}\n  finally{setActionBusy(false)}\n }\n\n async function deleteStudent(student:Student){\n  const identity=student.identityNumber||student.code;\n  const confirmed=window.confirm(\n   \"⚠️ حذف نهائي\\n\\n\"+\n   \"الطالب: \"+student.displayName+\"\\n\"+\n   \"رقم الهوية: \"+identity+\"\\n\\n\"+\n   \"سيتم حذف حساب الطالب وبياناته الأساسية نهائيًا وإزالته من الصف. \"+\n   \"استخدم الأرشفة بدل الحذف إذا أردت الاحتفاظ بالحساب.\\n\\nهل أنت متأكد؟\"\n  );\n  if(actionBusy||!confirmed)return;\n  setActionBusy(true);setError(\"\");setNotice(\"\");\n  try{\n   await teacherApi(\"/api/students\",{method:\"POST\",body:JSON.stringify({action:\"delete\",userId:student.userId})});\n   if(profile?.student.userId===student.userId)setProfile(null);\n   if(editingStudent?.userId===student.userId)setEditingStudent(null);\n   await Promise.all([loadStudents(selectedClassId),loadClasses()]);\n   setNotice(\"✓ تم حذف الطالب نهائيًا.\");\n  }catch(e){setError(e instanceof Error?e.message:\"تعذر حذف الطالب.\")}\n  finally{setActionBusy(false)}\n }\n\n function startEdit(student:Student){\n  const fallback=splitName(student.displayName);\n  setEditingStudent(student);\n  setEditFirstName(student.firstName||fallback.firstName);\n  setEditFamilyName(student.familyName||fallback.familyName);\n  setEditIdentityNumber(student.identityNumber||(/^\\d{9}$/.test(student.code)?student.code:\"\"));\n  setEditClassId(student.classId);\n  setEditPassword(\"\");\n  setCredentialBox(null);setError(\"\");setNotice(\"\");\n }\n\n async function saveStudentEdit(){\n  if(!editingStudent||!editFirstName.trim()||!editFamilyName.trim()||!validIdentity(editIdentityNumber)||!editClassId||actionBusy)return;\n  setActionBusy(true);setError(\"\");setNotice(\"\");\n  try{\n   await teacherApi<{ok:true;student:Student;passwordChanged:boolean}>(\"/api/students\",{method:\"POST\",body:JSON.stringify({\n    action:\"update\",userId:editingStudent.userId,firstName:editFirstName.trim(),familyName:editFamilyName.trim(),identityNumber:editIdentityNumber,classId:editClassId,password:editPassword\n   })});\n   const moved=editClassId!==selectedClassId;\n   setEditingStudent(null);setEditPassword(\"\");\n   await Promise.all([loadStudents(selectedClassId),loadClasses()]);\n   setNotice(moved?\"✓ تم تعديل الطالب ونقله إلى الصف المختار.\":\"✓ تم حفظ تعديلات الطالب.\");\n  }catch(e){setError(e instanceof Error?e.message:\"تعذر حفظ تعديلات الطالب.\")}\n  finally{setActionBusy(false)}\n }\n\n async function readBulkFile(file:File|null){\n  setBulkStudents([]);setBulkCredentials([]);setBulkErrors([]);setImportPreview([]);setBulkFileName(file?.name||\"\");setError(\"\");setNotice(\"\");\n  if(!file)return;\n  try{\n   const json=JSON.parse(await file.text());\n   const raw=Array.isArray(json)?json:Array.isArray(json?.students)?json.students:[];\n   const normalized:BulkStudent[]=raw.map((item:unknown)=>{\n    if(typeof item===\"string\"){\n     const names=splitName(item);\n     return {firstName:names.firstName,familyName:names.familyName,identityNumber:\"\"};\n    }\n    const x=item as Record<string,unknown>;\n    const directFirst=String(x?.firstName??x?.givenName??\"\").trim();\n    const directFamily=String(x?.familyName??x?.lastName??x?.surname??\"\").trim();\n    const names=(directFirst||directFamily)?{firstName:directFirst,familyName:directFamily}:splitName(x?.displayName??x?.name??x?.studentName??\"\");\n    const identityNumber=normalizeImportedIdentity(x?.identityNumber??x?.idNumber??x?.studentId??x?.identity??x?.id??x?.code??x?.studentCode??\"\");\n    return {firstName:names.firstName,familyName:names.familyName,identityNumber};\n   }).filter((x:BulkStudent)=>x.firstName||x.familyName||x.identityNumber);\n\n   if(!normalized.length)throw new Error(\"لم أجد بيانات طلاب في ملف JSON.\");\n   setBulkStudents(normalized);\n   setPreviewBusy(true);\n   const result=await teacherApi<{ok:true;preview:ImportPreviewRow[];valid:number;duplicates:number;invalid:number}>(\"/api/students\",{\n    method:\"POST\",body:JSON.stringify({action:\"previewImport\",classId:selectedClassId,students:normalized})\n   });\n   setImportPreview(result.preview||[]);\n   setNotice(\"✓ تمت معاينة الملف: \"+result.valid+\" صالح، \"+result.duplicates+\" مكرر، \"+result.invalid+\" غير صالح. لن يتم الحفظ قبل الضغط على زر الاستيراد.\");\n  }catch(e){\n   setError(e instanceof Error?e.message:\"ملف JSON غير صالح.\");\n   setBulkFileName(\"\");\n  }finally{setPreviewBusy(false)}\n }\n\n async function importBulkStudents(){\n  const validRows=importPreview.filter(x=>x.status===\"valid\");\n  if(!selectedClassId||!validRows.length||actionBusy)return;\n  setActionBusy(true);setError(\"\");setNotice(\"\");setBulkCredentials([]);setBulkErrors([]);\n  try{\n   const payload=validRows.map(x=>({firstName:x.firstName,familyName:x.familyName,identityNumber:x.identityNumber}));\n   const result=await teacherApi<{ok:true;imported:number;failed:number;credentials:Credential[];errors:BulkError[]}>(\"/api/students\",{\n    method:\"POST\",body:JSON.stringify({action:\"bulkImport\",classId:selectedClassId,students:payload})\n   });\n   setBulkCredentials(result.credentials||[]);\n   setBulkErrors(result.errors||[]);\n   await Promise.all([loadStudents(selectedClassId),loadClasses()]);\n   setNotice(\"✓ تم استيراد \"+result.imported+\" طالبًا\"+(result.failed?\"، وتعذر استيراد \"+result.failed+\".\":\".\"));\n   setBulkStudents([]);setBulkFileName(\"\");setImportPreview([]);\n  }catch(e){setError(e instanceof Error?e.message:\"تعذر استيراد الطلاب.\")}\n  finally{setActionBusy(false)}\n }\n\n function downloadCredentials(){\n  if(!bulkCredentials.length)return;\n  const payload={\n   classId:selectedClassId,\n   className:selectedClass?.name||\"\",\n   generatedAt:new Date().toISOString(),\n   students:bulkCredentials.map(x=>({\n    firstName:x.firstName||\"\",\n    familyName:x.familyName||\"\",\n    displayName:x.displayName||\"\",\n    identityNumber:x.identityNumber||x.code,\n    password:x.password\n   }))\n  };\n  const blob=new Blob([JSON.stringify(payload,null,2)],{type:\"application/json;charset=utf-8\"});\n  const url=URL.createObjectURL(blob);\n  const a=document.createElement(\"a\");\n  a.href=url;a.download=(selectedClass?.name||\"class\")+\"-student-credentials.json\";a.click();\n  URL.revokeObjectURL(url);\n }\n\n function exportCsv(){\n  const rows=[\n   [\"الاسم\",\"اسم العائلة\",\"رقم الهوية\",\"الصف\",\"الحالة\",\"آخر دخول\"],\n   ...visibleStudents.map(s=>[s.firstName,s.familyName,s.identityNumber||s.code,selectedClass?.name||\"\",statusLabel(s),s.lastLoginAt?fmtDate(s.lastLoginAt):\"لم يسجل الدخول\"])\n  ];\n  const csv=\"\\uFEFF\"+rows.map(row=>row.map(csvCell).join(\",\")).join(\"\\r\\n\");\n  const blob=new Blob([csv],{type:\"text/csv;charset=utf-8\"});\n  const url=URL.createObjectURL(blob);\n  const a=document.createElement(\"a\");\n  a.href=url;a.download=(selectedClass?.name||\"students\")+\"-students.csv\";a.click();\n  URL.revokeObjectURL(url);\n }\n\n async function openProfile(student:Student){\n  setProfileBusy(true);setError(\"\");\n  try{\n   const result=await teacherApi<{ok:true;profile:StudentProfile}>(\"/api/students?profileUserId=\"+encodeURIComponent(student.userId));\n   setProfile(result.profile);\n  }catch(e){setError(e instanceof Error?e.message:\"تعذر تحميل تفاصيل الطالب.\")}\n  finally{setProfileBusy(false)}\n }\n\n function toggleSelected(id:string){\n  setSelectedIds(prev=>prev.includes(id)?prev.filter(x=>x!==id):[...prev,id]);\n }\n\n function toggleSelectVisible(){\n  const visibleIds=visibleStudents.map(s=>s.userId);\n  const allSelected=visibleIds.length>0&&visibleIds.every(id=>selectedIds.includes(id));\n  if(allSelected)setSelectedIds(prev=>prev.filter(id=>!visibleIds.includes(id)));\n  else setSelectedIds(prev=>Array.from(new Set([...prev,...visibleIds])));\n }\n\n async function runBulkAction(operation:\"activate\"|\"deactivate\"|\"archive\"|\"unarchive\"|\"move\"|\"resetpasswords\"|\"delete\"){\n  if(!selectedIds.length||actionBusy)return;\n\n  const count=selectedIds.length;\n  if(operation===\"move\"&&!bulkTargetClassId){setError(\"اختر الصف الهدف أولًا.\");return}\n\n  let question=\"\";\n  if(operation===\"delete\")question=\"⚠️ حذف نهائي لـ \"+count+\" طالب؟\\n\\nالأرشفة أكثر أمانًا إذا كنت تريد الاحتفاظ بالبيانات.\";\n  else if(operation===\"archive\")question=\"أرشفة \"+count+\" طالب مع منع تسجيل الدخول والاحتفاظ بالبيانات؟\";\n  else if(operation===\"unarchive\")question=\"استعادة \"+count+\" طالب من الأرشيف وتفعيل حساباتهم؟\";\n  else if(operation===\"resetpasswords\")question=\"إنشاء كلمات مرور جديدة لـ \"+count+\" طالب؟ ستظهر الكلمات الجديدة مرة واحدة بعد العملية.\";\n  else if(operation===\"move\")question=\"نقل \"+count+\" طالب إلى الصف المختار؟\";\n  if(question&&!window.confirm(question))return;\n\n  setActionBusy(true);setError(\"\");setNotice(\"\");setBulkErrors([]);\n  try{\n   const result=await teacherApi<{ok:true;processed:number;failed:number;credentials:Credential[];errors:BulkError[]}>(\"/api/students\",{\n    method:\"POST\",\n    body:JSON.stringify({action:\"bulkAction\",operation,userIds:selectedIds,targetClassId:bulkTargetClassId})\n   });\n   if(result.credentials?.length)setBulkCredentials(result.credentials);\n   if(result.errors?.length)setBulkErrors(result.errors);\n   await Promise.all([loadStudents(selectedClassId),loadClasses()]);\n   setSelectedIds([]);\n   setNotice(\"✓ نُفذت العملية على \"+result.processed+\" طالب\"+(result.failed?\"، وفشلت لدى \"+result.failed+\".\":\".\"));\n  }catch(e){setError(e instanceof Error?e.message:\"تعذر تنفيذ العملية الجماعية.\")}\n  finally{setActionBusy(false)}\n }\n\n function sortButton(key:SortKey,label:string){\n  return <button className=\"student-sort-button\" onClick={()=>{if(sortKey===key)setSortAsc(x=>!x);else{setSortKey(key);setSortAsc(true)}}}>\n   {label} {sortKey===key?(sortAsc?\"↑\":\"↓\"):\"↕\"}\n  </button>;\n }\n\n const selectedCount=selectedIds.length;\n const previewValid=importPreview.filter(x=>x.status===\"valid\").length;\n const previewDuplicates=importPreview.filter(x=>x.status===\"duplicate\").length;\n const previewInvalid=importPreview.filter(x=>x.status===\"invalid\").length;\n\n return <section className=\"teacher-platform\" dir=\"rtl\"><div className=\"teacher-platform-inner\">\n  <section className=\"platform-hero\">\n   <div><span className=\"platform-eyebrow\">ExamBank 2.0H</span><h2>إدارة الطلاب المتقدمة</h2><p>بحث وفرز، عمليات جماعية، معاينة استيراد، أرشفة، ملف طالب، علامات وتصدير.</p></div>\n   <div className=\"platform-hero-stat\"><strong>{classes.filter(c=>c.active).length}</strong><span>صفوف فعّالة</span></div>\n  </section>\n\n  {error&&<div className=\"platform-error\">{error}</div>}\n  {notice&&<div className=\"platform-notice\">{notice}</div>}\n\n  {credentialBox&&<section className=\"credential-box\">\n   <div><span className=\"platform-eyebrow\">بيانات دخول جديدة</span><h3>{credentialBox.name}</h3></div>\n   <div className=\"credential-values\">\n    <div><span>رقم الهوية / الدخول</span><strong>{credentialBox.identityNumber}</strong></div>\n    <div><span>كلمة المرور</span><strong>{credentialBox.password}</strong></div>\n   </div>\n   <div className=\"student-row-actions\">\n    <button onClick={()=>void copyText(credentialText(credentialBox.name,credentialBox.identityNumber,credentialBox.password),\"✓ تم نسخ بيانات الدخول.\")}>📋 نسخ بيانات الدخول</button>\n    <button onClick={()=>setCredentialBox(null)}>إخفاء</button>\n   </div>\n  </section>}\n\n  <div className=\"platform-grid\">\n   <section className=\"platform-card\">\n    <div className=\"platform-card-heading\"><div><span className=\"platform-eyebrow\">Classes</span><h3>الصفوف</h3></div><button onClick={()=>loadClasses()} disabled={loading}>↻ تحديث</button></div>\n    <div className=\"platform-form-grid\">\n     <label>اسم الصف<input value={newClassName} onChange={e=>setNewClassName(e.target.value)} placeholder=\"مثال: الثاني عشر 8\"/></label>\n     <label>المرحلة / الصف<input value={newClassGrade} onChange={e=>setNewClassGrade(e.target.value)} placeholder=\"مثال: الثاني عشر\"/></label>\n     <label>السنة الدراسية<input value={newSchoolYear} onChange={e=>setNewSchoolYear(e.target.value)}/></label>\n     <button className=\"platform-primary\" onClick={createClass} disabled={actionBusy||!newClassName.trim()}>+ إنشاء صف</button>\n    </div>\n    {loading&&classes.length===0&&<div className=\"platform-loading\">⏳ جارٍ التحميل...</div>}\n    <div className=\"class-list\">\n     {classes.map(classroom=><article key={classroom.classId} className={\"class-row \"+(classroom.classId===selectedClassId?\"selected \":\"\")+(classroom.active?\"\":\"archived\")}>\n      <button className=\"class-select\" onClick={()=>setSelectedClassId(classroom.classId)}><strong>{classroom.name}</strong><span>{classroom.grade||\"—\"} · {classroom.studentCount} طالب</span><small>{classroom.schoolYear||\"\"}</small></button>\n      <button className=\"class-archive\" onClick={()=>toggleClassArchive(classroom)} disabled={actionBusy}>{classroom.active?\"أرشفة\":\"تفعيل\"}</button>\n     </article>)}\n     {!loading&&classes.length===0&&<div className=\"platform-empty\">لا توجد صفوف بعد.</div>}\n    </div>\n   </section>\n\n   <section className=\"platform-card student-admin-card\">\n    <div className=\"platform-card-heading\"><div><span className=\"platform-eyebrow\">Students</span><h3>الطلاب</h3></div><span className=\"student-count-badge\">{students.length}</span></div>\n    {!selectedClass?<div className=\"platform-empty\">أنشئ صفًا أو اختر صفًا لإدارة الطلاب.</div>:<>\n     <div className=\"selected-class-strip\"><strong>{selectedClass.name}</strong><span>{selectedClass.grade||\"\"}</span></div>\n\n     <div className=\"student-admin-stats\">\n      <article><strong>{stats.total}</strong><span>إجمالي</span></article>\n      <article><strong>{stats.active}</strong><span>فعّال</span></article>\n      <article><strong>{stats.disabled}</strong><span>معطّل</span></article>\n      <article><strong>{stats.archived}</strong><span>مؤرشف</span></article>\n      <article><strong>{stats.neverLogged}</strong><span>لم يدخلوا بعد</span></article>\n     </div>\n\n     <div className=\"student-admin-toolbar\">\n      <input value={searchText} onChange={e=>setSearchText(e.target.value)} placeholder=\"🔎 ابحث بالاسم، العائلة أو رقم الهوية\"/>\n      <select value={statusFilter} onChange={e=>setStatusFilter(e.target.value as StatusFilter)}>\n       <option value=\"all\">كل الحالات</option><option value=\"active\">فعّال</option><option value=\"disabled\">معطّل</option><option value=\"archived\">مؤرشف</option>\n      </select>\n      <button onClick={exportCsv}>⬇ Excel / CSV</button>\n     </div>\n\n     <details className=\"student-admin-details\">\n      <summary>➕ إضافة طالب جديد</summary>\n      <div className=\"student-create-grid\">\n       <label>الاسم<input value={newFirstName} onChange={e=>setNewFirstName(e.target.value)} placeholder=\"الاسم الشخصي\"/></label>\n       <label>اسم العائلة<input value={newFamilyName} onChange={e=>setNewFamilyName(e.target.value)} placeholder=\"اسم العائلة\"/></label>\n       <label>رقم الهوية<input value={newIdentityNumber} onChange={e=>setNewIdentityNumber(onlyDigits(e.target.value))} inputMode=\"numeric\" maxLength={9} dir=\"ltr\" placeholder=\"9 أرقام\"/></label>\n       <label>كلمة مرور اختيارية<input type=\"password\" value={newStudentPassword} onChange={e=>setNewStudentPassword(e.target.value)} placeholder=\"اتركها فارغة للتوليد التلقائي\"/></label>\n       <button className=\"platform-primary\" onClick={createStudent} disabled={actionBusy||!selectedClass.active||!newFirstName.trim()||!newFamilyName.trim()||!validIdentity(newIdentityNumber)}>+ إنشاء حساب طالب</button>\n      </div>\n     </details>\n\n     <details className=\"student-admin-details\">\n      <summary>⬆ استيراد طلاب من JSON مع معاينة قبل الحفظ</summary>\n      <div className=\"student-create-grid\">\n       <label>ملف الطلاب<input type=\"file\" accept=\".json,application/json\" onChange={e=>void readBulkFile(e.target.files?.[0]||null)}/></label>\n       <div><span>الملف</span><strong>{bulkFileName||\"لم يتم اختيار ملف\"}</strong><small>{previewBusy?\" جارٍ فحص البيانات...\":importPreview.length?` ${previewValid} صالح · ${previewDuplicates} مكرر · ${previewInvalid} غير صالح`:\"\"}</small></div>\n       <button className=\"platform-primary\" onClick={importBulkStudents} disabled={actionBusy||previewBusy||!selectedClass.active||!previewValid}>✓ استيراد {previewValid||\"\"} طالب صالح</button>\n      </div>\n\n      {importPreview.length>0&&<div className=\"students-table-wrap import-preview-wrap\"><table className=\"students-table\">\n       <thead><tr><th>الحالة</th><th>الاسم</th><th>العائلة</th><th>رقم الهوية</th><th>ملاحظة</th></tr></thead>\n       <tbody>{importPreview.map(row=><tr key={row.index} className={\"import-row-\"+row.status}>\n        <td><span className={\"import-badge \"+row.status}>{row.status===\"valid\"?\"✓ صالح\":row.status===\"duplicate\"?\"⚠ مكرر\":\"✕ خطأ\"}</span></td>\n        <td>{row.firstName||\"—\"}</td><td>{row.familyName||\"—\"}</td><td dir=\"ltr\">{row.identityNumber||\"—\"}</td>\n        <td>{row.error||\"جاهز للاستيراد\"}</td>\n       </tr>)}</tbody>\n      </table></div>}\n     </details>\n\n     {!selectedClass.active&&<div className=\"platform-warning\">الصف مؤرشف؛ فعّله قبل إضافة أو استعادة الطلاب.</div>}\n\n     {selectedCount>0&&<section className=\"student-bulk-bar\">\n      <strong>{selectedCount} طالب محدد</strong>\n      <button onClick={()=>void runBulkAction(\"activate\")} disabled={actionBusy}>تفعيل</button>\n      <button onClick={()=>void runBulkAction(\"deactivate\")} disabled={actionBusy}>تعطيل</button>\n      <button onClick={()=>void runBulkAction(\"archive\")} disabled={actionBusy}>أرشفة</button>\n      <button onClick={()=>void runBulkAction(\"unarchive\")} disabled={actionBusy}>استعادة</button>\n      <button onClick={()=>void runBulkAction(\"resetpasswords\")} disabled={actionBusy}>🔑 كلمات مرور جديدة</button>\n      <select value={bulkTargetClassId} onChange={e=>setBulkTargetClassId(e.target.value)}>\n       <option value=\"\">اختر صفًا للنقل</option>\n       {classes.filter(c=>c.active&&c.classId!==selectedClassId).map(c=><option key={c.classId} value={c.classId}>{c.name}</option>)}\n      </select>\n      <button onClick={()=>void runBulkAction(\"move\")} disabled={actionBusy||!bulkTargetClassId}>نقل</button>\n      <button className=\"danger-button\" onClick={()=>void runBulkAction(\"delete\")} disabled={actionBusy}>🗑 حذف نهائي</button>\n      <button onClick={()=>setSelectedIds([])}>إلغاء التحديد</button>\n     </section>}\n\n     {bulkCredentials.length>0&&<section className=\"credential-box\" style={{marginTop:16}}>\n      <div className=\"platform-card-heading\"><div><span className=\"platform-eyebrow\">Generated credentials</span><h3>بيانات الدخول الجديدة</h3></div><button onClick={downloadCredentials}>⬇ تنزيل JSON</button></div>\n      <p>احفظ هذه البيانات الآن؛ كلمات المرور لا تُعرض لاحقًا كنص واضح.</p>\n      <div className=\"students-table-wrap\"><table className=\"students-table\">\n       <thead><tr><th>الاسم</th><th>العائلة</th><th>رقم الهوية</th><th>كلمة المرور</th><th></th></tr></thead>\n       <tbody>{bulkCredentials.map((c,i)=>{\n        const fullName=(c.firstName||\"\")+\" \"+(c.familyName||\"\");\n        const identity=c.identityNumber||c.code;\n        return <tr key={(c.userId||c.code)+i}><td>{c.firstName}</td><td>{c.familyName}</td><td dir=\"ltr\">{identity}</td><td dir=\"ltr\"><strong>{c.password}</strong></td>\n         <td><button onClick={()=>void copyText(credentialText(fullName.trim(),identity,c.password),\"✓ تم نسخ بيانات دخول الطالب.\")}>📋 نسخ</button></td></tr>\n       })}</tbody>\n      </table></div>\n     </section>}\n\n     {bulkErrors.length>0&&<div className=\"platform-warning\"><strong>عمليات لم تكتمل:</strong>{bulkErrors.map((x,i)=><div key={x.userId||i}>{x.displayName||x.userId||\"السطر \"+((x.index??i)+1)}: {x.error}</div>)}</div>}\n\n     {editingStudent&&<section className=\"credential-box\" style={{marginTop:16}}>\n      <div className=\"platform-card-heading\"><div><span className=\"platform-eyebrow\">Edit Student</span><h3>تعديل تفاصيل الطالب</h3></div><button onClick={()=>setEditingStudent(null)}>إلغاء</button></div>\n      <div className=\"student-create-grid\">\n       <label>الاسم<input value={editFirstName} onChange={e=>setEditFirstName(e.target.value)}/></label>\n       <label>اسم العائلة<input value={editFamilyName} onChange={e=>setEditFamilyName(e.target.value)}/></label>\n       <label>رقم الهوية<input value={editIdentityNumber} onChange={e=>setEditIdentityNumber(onlyDigits(e.target.value))} inputMode=\"numeric\" maxLength={9} dir=\"ltr\"/></label>\n       <label>الصف<select value={editClassId} onChange={e=>setEditClassId(e.target.value)}>{classes.filter(c=>c.active||c.classId===(editingStudent?.classId||\"\")).map(c=><option key={c.classId} value={c.classId}>{c.name} · {c.grade}</option>)}</select></label>\n       <label>كلمة مرور جديدة<input type=\"password\" value={editPassword} onChange={e=>setEditPassword(e.target.value)} placeholder=\"اتركها فارغة للإبقاء على الحالية\"/></label>\n       <button className=\"platform-primary\" onClick={saveStudentEdit} disabled={actionBusy||!editFirstName.trim()||!editFamilyName.trim()||!validIdentity(editIdentityNumber)||!editClassId}>💾 حفظ التعديلات</button>\n      </div>\n     </section>}\n\n     {profileBusy&&<div className=\"platform-loading\">⏳ جارٍ تحميل ملف الطالب...</div>}\n     {profile&&<section className=\"student-profile-card\">\n      <div className=\"platform-card-heading\">\n       <div><span className=\"platform-eyebrow\">Student Profile</span><h3>{profile.student.displayName}</h3><small>{profile.classroom?.name||\"—\"} · {profile.student.identityNumber}</small></div>\n       <button onClick={()=>setProfile(null)}>إغلاق</button>\n      </div>\n      <div className=\"student-profile-stats\">\n       <article><strong>{profile.stats.assigned}</strong><span>واجبات</span></article>\n       <article><strong>{profile.stats.completed}</strong><span>مكتملة</span></article>\n       <article><strong>{profile.stats.pending}</strong><span>لم تُحل</span></article>\n       <article><strong>{profile.stats.average===null?\"—\":profile.stats.average+\"%\"}</strong><span>المعدل</span></article>\n      </div>\n      <p><b>آخر دخول:</b> {profile.stats.lastLoginAt?fmtDate(profile.stats.lastLoginAt):\"لم يسجل الدخول بعد\"} · <b>إنشاء الحساب:</b> {fmtDate(profile.student.createdAt)}</p>\n      <div className=\"students-table-wrap\"><table className=\"students-table\">\n       <thead><tr><th>الواجب</th><th>الحالة</th><th>المحاولات</th><th>العلامة</th><th>النسبة</th><th>آخر تسليم</th></tr></thead>\n       <tbody>{profile.assignments.map(a=><tr key={a.assignmentId}>\n        <td>{a.title}</td><td>{a.latestScore===null?\"لم يُحل\":a.finalized?\"مصحح\":\"بانتظار المراجعة\"}</td><td>{a.attemptsUsed}</td>\n        <td>{a.latestScore===null?\"—\":a.latestScore+\"/\"+a.totalMarks}</td><td>{a.latestPercentage===null?\"—\":a.latestPercentage+\"%\"}</td><td>{a.submittedAt?fmtDate(a.submittedAt):\"—\"}</td>\n       </tr>)}{!profile.assignments.length&&<tr><td colSpan={6}>لا توجد واجبات لهذا الصف.</td></tr>}</tbody>\n      </table></div>\n     </section>}\n\n     <div className=\"student-sort-row\">\n      <span>الفرز:</span>{sortButton(\"firstName\",\"الاسم\")}{sortButton(\"familyName\",\"العائلة\")}{sortButton(\"identityNumber\",\"الهوية\")}{sortButton(\"status\",\"الحالة\")}\n     </div>\n\n     <div className=\"students-table-wrap\"><table className=\"students-table\">\n      <thead><tr>\n       <th><input type=\"checkbox\" checked={visibleStudents.length>0&&visibleStudents.every(s=>selectedIds.includes(s.userId))} onChange={toggleSelectVisible} aria-label=\"تحديد الكل\"/></th>\n       <th>الاسم</th><th>اسم العائلة</th><th>رقم الهوية</th><th>الحالة</th><th>آخر دخول</th><th>إجراءات</th>\n      </tr></thead>\n      <tbody>{visibleStudents.map(student=><tr key={student.userId} className={student.archived?\"student-row-archived\":\"\"}>\n       <td><input type=\"checkbox\" checked={selectedIds.includes(student.userId)} onChange={()=>toggleSelected(student.userId)} aria-label={\"تحديد \"+student.displayName}/></td>\n       <td><strong>{student.firstName||splitName(student.displayName).firstName}</strong></td>\n       <td>{student.familyName||splitName(student.displayName).familyName||\"—\"}</td>\n       <td dir=\"ltr\">{student.identityNumber||student.code||\"يحتاج تحديث\"}</td>\n       <td><span className={student.archived?\"status-archived\":student.active?\"status-active\":\"status-disabled\"}>{statusLabel(student)}</span></td>\n       <td>{student.lastLoginAt?fmtDate(student.lastLoginAt):<span className=\"never-login\">لم يدخل بعد</span>}</td>\n       <td><div className=\"student-row-actions\">\n        <button onClick={()=>void openProfile(student)} disabled={actionBusy}>👤 التفاصيل</button>\n        <button onClick={()=>startEdit(student)} disabled={actionBusy}>✏️ تعديل</button>\n        <button onClick={()=>void copyText(student.identityNumber||student.code,\"✓ تم نسخ رقم الهوية.\")}>📋 الهوية</button>\n        {!student.archived&&<button onClick={()=>resetPassword(student)} disabled={actionBusy}>كلمة مرور جديدة</button>}\n        {!student.archived&&<button onClick={()=>toggleStudent(student)} disabled={actionBusy}>{student.active?\"تعطيل\":\"تفعيل\"}</button>}\n        <button onClick={()=>archiveStudent(student)} disabled={actionBusy}>{student.archived?\"↩ استعادة\":\"📦 أرشفة\"}</button>\n        <button className=\"danger-button\" onClick={()=>deleteStudent(student)} disabled={actionBusy}>🗑 حذف</button>\n       </div></td>\n      </tr>)}</tbody>\n     </table>\n     {!loading&&visibleStudents.length===0&&<div className=\"platform-empty\">لا توجد نتائج مطابقة.</div>}\n     </div>\n    </>}\n   </section>\n  </div>\n\n  <AssignmentsPanel token={token} classes={classes} currentExam={currentExam}/>\n </div></section>;\n}\n\nexport default TeacherPlatform;\n";
const cssBlock = "\n/* ============================================================\n   ExamBank 2.0H - Advanced student administration\n   ============================================================ */\n\n.student-admin-card {\n  min-width: 0;\n}\n\n.student-admin-stats,\n.student-profile-stats {\n  display: grid;\n  grid-template-columns: repeat(5, minmax(82px, 1fr));\n  gap: 8px;\n  margin: 12px 0;\n}\n\n.student-admin-stats article,\n.student-profile-stats article {\n  border: 1px solid #e2e8f0;\n  background: #f8fafc;\n  border-radius: 12px;\n  padding: 10px;\n  text-align: center;\n}\n\n.student-admin-stats strong,\n.student-profile-stats strong {\n  display: block;\n  font-size: 20px;\n  color: #0f172a;\n}\n\n.student-admin-stats span,\n.student-profile-stats span {\n  display: block;\n  margin-top: 2px;\n  color: #64748b;\n  font-size: 11px;\n  font-weight: 800;\n}\n\n.student-admin-toolbar,\n.student-sort-row,\n.student-bulk-bar {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n\n.student-admin-toolbar {\n  margin: 10px 0;\n  padding: 10px;\n  border: 1px solid #e2e8f0;\n  border-radius: 12px;\n  background: #fff;\n}\n\n.student-admin-toolbar input {\n  flex: 1 1 260px;\n  min-width: 180px;\n  border: 1px solid #cbd5e1;\n  border-radius: 9px;\n  padding: 9px 10px;\n  font: inherit;\n}\n\n.student-admin-toolbar select,\n.student-bulk-bar select,\n.student-create-grid select {\n  border: 1px solid #cbd5e1;\n  border-radius: 9px;\n  padding: 9px 10px;\n  background: #fff;\n  font: inherit;\n}\n\n.student-admin-toolbar button,\n.student-sort-row button,\n.student-bulk-bar button,\n.student-profile-card button,\n.import-preview-wrap button {\n  border: 1px solid #cbd5e1;\n  border-radius: 8px;\n  background: #fff;\n  padding: 7px 9px;\n  cursor: pointer;\n  font-size: 11px;\n  font-weight: 800;\n}\n\n.student-admin-details {\n  margin-top: 10px;\n  border: 1px solid #e2e8f0;\n  border-radius: 12px;\n  background: #fff;\n  overflow: hidden;\n}\n\n.student-admin-details summary {\n  padding: 11px 13px;\n  cursor: pointer;\n  font-weight: 900;\n  color: #334155;\n  background: #f8fafc;\n}\n\n.student-admin-details[open] summary {\n  border-bottom: 1px solid #e2e8f0;\n}\n\n.student-admin-details .student-create-grid {\n  border: 0;\n  border-radius: 0;\n}\n\n.student-bulk-bar {\n  position: sticky;\n  top: 8px;\n  z-index: 4;\n  margin: 12px 0;\n  padding: 10px;\n  border: 1px solid #bfdbfe;\n  border-radius: 12px;\n  background: #eff6ff;\n  box-shadow: 0 8px 20px rgba(15,23,42,.08);\n}\n\n.student-bulk-bar strong {\n  color: #1d4ed8;\n  margin-left: 4px;\n}\n\n.danger-button {\n  color: #b42318 !important;\n  border-color: #fecaca !important;\n  background: #fff7f7 !important;\n}\n\n.status-archived {\n  display: inline-flex;\n  border-radius: 999px;\n  padding: 4px 8px;\n  font-size: 10px;\n  font-weight: 900;\n  background: #f1f5f9;\n  color: #475569;\n}\n\n.student-row-archived {\n  opacity: .72;\n  background: #fafafa;\n}\n\n.never-login {\n  color: #9a6700;\n  font-weight: 800;\n}\n\n.student-sort-row {\n  margin-top: 12px;\n  color: #64748b;\n  font-size: 12px;\n  font-weight: 800;\n}\n\n.student-sort-button {\n  min-width: 72px;\n}\n\n.import-preview-wrap {\n  max-height: 320px;\n  overflow: auto;\n  margin: 0 12px 12px;\n}\n\n.import-badge {\n  display: inline-flex;\n  padding: 4px 7px;\n  border-radius: 999px;\n  font-size: 10px;\n  font-weight: 900;\n}\n\n.import-badge.valid {\n  background: #dcfce7;\n  color: #166534;\n}\n\n.import-badge.duplicate {\n  background: #fef3c7;\n  color: #92400e;\n}\n\n.import-badge.invalid {\n  background: #fee2e2;\n  color: #991b1b;\n}\n\n.import-row-duplicate {\n  background: #fffbeb;\n}\n\n.import-row-invalid {\n  background: #fff7f7;\n}\n\n.student-profile-card {\n  margin-top: 14px;\n  border: 1px solid #bfdbfe;\n  background: #f8fbff;\n  border-radius: 16px;\n  padding: 14px;\n}\n\n.student-profile-card p {\n  color: #475569;\n  font-size: 12px;\n}\n\n.student-profile-stats {\n  grid-template-columns: repeat(4, minmax(90px, 1fr));\n}\n\n.credential-box .student-row-actions {\n  margin-top: 10px;\n}\n\n@media (max-width: 980px) {\n  .student-admin-stats {\n    grid-template-columns: repeat(2, minmax(110px, 1fr));\n  }\n  .student-profile-stats {\n    grid-template-columns: repeat(2, minmax(110px, 1fr));\n  }\n}\n";

fs.writeFileSync(files.backend, backend, "utf8");
fs.writeFileSync(files.login, login, "utf8");
fs.writeFileSync(files.frontend, frontend, "utf8");

let css = fs.readFileSync(files.css, "utf8");
const marker = "ExamBank 2.0H - Advanced student administration";
if (!css.includes(marker)) {
  css = css.replace(/\s*$/, "") + "\n\n" + cssBlock.trim() + "\n";
  fs.writeFileSync(files.css, css, "utf8");
}

console.log("Updated api/src/functions/manage-students.js");
console.log("Updated api/src/functions/platform-login.js");
console.log("Updated src/TeacherPlatform.tsx");
console.log("Updated src/platform.css");

console.log("\nChecking backend syntax...");
execSync('node --check "api/src/functions/manage-students.js"', { cwd: root, stdio: "inherit", shell: true });
execSync('node --check "api/src/functions/platform-login.js"', { cwd: root, stdio: "inherit", shell: true });

console.log("\nRunning project build...\n");
execSync("npm run build", { cwd: root, stdio: "inherit", shell: true });

console.log("\nPhase 2.0H Advanced Student Administration installed successfully.");
